package architests

import (
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"testing"

	"github.com/Snowflake-Labs/terraform-provider-snowflake/pkg/architest"
)

// generatedFileNameRegex matches the names generators write. Only these files carry the generator header.
var generatedFileNameRegex = regexp.MustCompile(`_gen(_test)?\.go$`)

// extFileNameRegex matches hand-written extensions of generated files, e.g. warehouse_adaptive_ext_test.go extends warehouse_adaptive.
// The first group is the generated file's stem, i.e. the name without the _ext suffix.
var extFileNameRegex = regexp.MustCompile(`^(.+)_ext(_test)?\.go$`)

const generatedHeaderPrefix = "// Code generated by "

func TestArchCheck_FileNaming_Resources(t *testing.T) {
	assertFileNamingConventions(t, "../resources/")
}

func TestArchCheck_FileNaming_Datasources(t *testing.T) {
	assertFileNamingConventions(t, "../datasources/")
}

func assertFileNamingConventions(t *testing.T, directory string) {
	t.Helper()
	files := architest.Directory(directory).AllFiles()

	names := make(map[string]bool)
	files.All(func(file *architest.File) {
		names[filepath.Base(file.Name())] = true
	})

	files.All(func(file *architest.File) {
		path := file.Name()
		name := filepath.Base(path)

		content, err := os.ReadFile(filepath.Clean(path))
		if err != nil {
			t.Fatalf("reading %s: %v", path, err)
		}
		isGenerated := strings.HasPrefix(string(content), generatedHeaderPrefix)
		isGeneratedName := generatedFileNameRegex.MatchString(name)

		// Generated files are named _gen.go or _gen_test.go, and only those carry the generator header.
		if isGeneratedName && !isGenerated {
			t.Errorf("%s: generated file name without the generator header", path)
		}
		if isGenerated && !isGeneratedName {
			t.Errorf("%s: generator header in a file that is not named _gen.go or _gen_test.go", path)
		}

		// A hand-written extension must extend a generated file of the same stem.
		if match := extFileNameRegex.FindStringSubmatch(name); match != nil {
			if !names[match[1]+"_gen.go"] {
				t.Errorf("%s: extension without the generated file %s_gen.go", path, match[1])
			}
		}
	})
}
